//! noevia#1318: native read-only `GET /api/v1/models/updates` through the real router.
//!
//! On Linux every case of `fixtures/model-updates-python.v1.json` (the actual services Python,
//! regenerated by CI from the pinned ref) runs through the router and the kernel-contained
//! opener. Elsewhere that opener refuses by design, which the refusal test asserts; the lib
//! tests run the same cases on every platform through the synthetic root.
#![cfg(feature = "native-model-updates")]
#![allow(
    clippy::unwrap_used,
    clippy::expect_used,
    clippy::panic,
    clippy::indexing_slicing
)]
use axum::{body::Body, http::Request};
use http_body_util::BodyExt;
use noevia_model_manager::{
    model_updates::ModelUpdates, Container, DockerRead, Redactor, StateData,
};
use rusqlite::Connection;
use std::{future::Future, path::Path, pin::Pin, sync::Arc};
use tower::ServiceExt;

const TOKEN: &str = "synthetic-model-loader-token-0123456789abcdef";
const PATH: &str = "/api/v1/models/updates";
const REFUSED: &[u8] = br#"{"detail":"Native model update status is unavailable"}"#;

type Job<'a, T> = Pin<Box<dyn Future<Output = Result<T, &'static str>> + Send + 'a>>;
struct NoDocker;
impl DockerRead for NoDocker {
    fn containers(&self) -> Job<'_, Vec<Container>> {
        Box::pin(async { Err("not used") })
    }
    fn logs<'a>(&'a self, _: &'a str, _: usize) -> Job<'a, Vec<u8>> {
        Box::pin(async { Err("not used") })
    }
}

/// `roots` is (models, ini, data); `None` is the default python selector.
fn state(roots: Option<(&Path, &Path, &Path)>, legacy_base: &str) -> Arc<StateData> {
    Arc::new(StateData {
        #[cfg(feature = "native-diagnose")]
        diagnosis: None,
        #[cfg(feature = "native-prompts")]
        prompts: None,
        #[cfg(feature = "native-settings")]
        settings: None,
        model_updates: roots
            .map(|(models, ini, data)| Arc::new(ModelUpdates::new(models, ini, data))),
        #[cfg(feature = "native-model-detail")]
        model_detail: None,
        #[cfg(feature = "native-model-list")]
        model_list: None,
        sections: None,
        embedding: None,
        host: None,
        token: TOKEN.into(),
        configured: vec![],
        docker: Arc::new(NoDocker),
        redactor: Redactor::new().unwrap(),
        permits: tokio::sync::Semaphore::new(4),
        legacy: noevia_model_manager::legacy_client().unwrap(),
        legacy_base: legacy_base.into(),
        idle_unload: None,
        #[cfg(feature = "native-download-targets")]
        download_targets: None,
        #[cfg(feature = "native-badges")]
        badges: None,
        #[cfg(feature = "native-bench-runs")]
        bench_runs: None,
        #[cfg(feature = "native-section-writes")]
        section_writes: None,
        #[cfg(feature = "native-settings-write")]
        settings_write: None,
        #[cfg(feature = "native-benchmark-overview")]
        benchmark_overview: None,
        #[cfg(feature = "native-check-updates")]
        check_updates: None,
        #[cfg(feature = "native-downloads")]
        downloads: None,
        #[cfg(feature = "native-model-delete")]
        model_delete: None,
        #[cfg(feature = "native-draft-heads")]
        draft_heads: None,
        #[cfg(feature = "native-backends")]
        backend_stats: None,
        #[cfg(feature = "native-benchmark-runner")]
        bench_runner: None,
        #[cfg(feature = "native-backend-control")]
        backends: None,
    })
}

struct Answer {
    status: u16,
    content_type: Option<String>,
    body: Vec<u8>,
}

async fn send(state: Arc<StateData>, method: &str, path: &str, token: bool) -> Answer {
    let mut request = Request::builder().method(method).uri(path);
    if token {
        request = request.header("x-model-loader-token", TOKEN);
    }
    let response = noevia_model_manager::router(state)
        .oneshot(request.body(Body::empty()).unwrap())
        .await
        .unwrap();
    Answer {
        status: response.status().as_u16(),
        content_type: response
            .headers()
            .get("content-type")
            .map(|v| v.to_str().unwrap().to_owned()),
        body: response
            .into_body()
            .collect()
            .await
            .unwrap()
            .to_bytes()
            .to_vec(),
    }
}

/// A store with one synthetic row, under `root/data`.
fn store(root: &Path) -> std::path::PathBuf {
    let data = root.join("data");
    std::fs::create_dir_all(&data).unwrap();
    Connection::open(data.join("model_loader.db"))
        .unwrap()
        .execute_batch(
            "CREATE TABLE update_check (filename TEXT PRIMARY KEY, repo_id TEXT NOT NULL, hf_last_modified TEXT, checked_at REAL NOT NULL);
             INSERT INTO update_check VALUES('synthetic.gguf', 'synthetic/repo', '2024-05-01T00:00:00Z', 1.5);",
        )
        .unwrap();
    data
}

#[tokio::test]
async fn missing_models_folder_and_store_failures_have_pythons_shape() {
    let dir = tempfile::tempdir().unwrap();
    let models = dir.path().join("models");
    let ini = models.join("models.ini");
    let data = store(dir.path());
    let ok = send(
        state(Some((&models, &ini, &data)), "http://127.0.0.1:9"),
        "GET",
        PATH,
        true,
    )
    .await;
    assert_eq!(ok.status, 200);
    assert_eq!(ok.content_type.as_deref(), Some("application/json"));
    assert_eq!(ok.body, br#"{"status":{}}"#);
    // No store: Python's sqlite3 would create one and then raise; native answers the same 500
    // without creating anything.
    let empty = dir.path().join("empty");
    let failed = send(
        state(Some((&models, &ini, &empty)), "http://127.0.0.1:9"),
        "GET",
        PATH,
        true,
    )
    .await;
    assert_eq!(failed.status, 500);
    assert_eq!(
        failed.content_type.as_deref(),
        Some("text/plain; charset=utf-8")
    );
    assert_eq!(failed.body, b"Internal Server Error");
    assert!(!empty.exists());
}

#[tokio::test]
async fn walk_refusal_is_the_native_503() {
    let dir = tempfile::tempdir().unwrap();
    let models = dir.path().join("models");
    std::fs::create_dir(&models).unwrap();
    let outside = dir.path().join("outside.gguf");
    std::fs::write(&outside, b"").unwrap();
    // A link leaving the models folder: the contained walker refuses instead of following it
    // (and off Linux the contained opener refuses every folder).
    std::os::unix::fs::symlink(&outside, models.join("escape.gguf")).unwrap();
    let data = store(dir.path());
    let answer = send(
        state(
            Some((&models, &models.join("models.ini"), &data)),
            "http://127.0.0.1:9",
        ),
        "GET",
        PATH,
        true,
    )
    .await;
    assert_eq!(answer.status, 503);
    assert_eq!(answer.body, REFUSED);
}

#[cfg(target_os = "linux")]
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn actual_python_differential_through_router() {
    let fixture: serde_json::Value =
        serde_json::from_str(include_str!("fixtures/model-updates-python.v1.json")).unwrap();
    for case in fixture["cases"].as_array().unwrap() {
        let id = case["id"].as_str().unwrap();
        let dir = tempfile::tempdir().unwrap();
        let (models, ini, data) = support::build(dir.path(), case);
        support::modes(&models, case, false);
        let answer = send(
            state(Some((&models, &ini, &data)), "http://127.0.0.1:9"),
            "GET",
            PATH,
            true,
        )
        .await;
        support::modes(&models, case, true);
        assert_eq!(
            u64::from(answer.status),
            case["status"].as_u64().unwrap(),
            "{id}"
        );
        assert_eq!(
            answer.content_type.as_deref(),
            case["content_type"].as_str(),
            "{id}"
        );
        assert_eq!(
            String::from_utf8(answer.body).unwrap(),
            case["body"].as_str().unwrap(),
            "{id}"
        );
    }
}

#[cfg(target_os = "linux")]
mod support {
    //! Mirror of the lib test builder (the lib's is private to the crate's unit tests).
    use rusqlite::Connection;
    use serde_json::Value;
    use std::path::{Path, PathBuf};
    use std::time::{Duration, SystemTime, UNIX_EPOCH};

    fn hex(text: &str) -> Vec<u8> {
        (0..text.len())
            .step_by(2)
            .map(|i| u8::from_str_radix(&text[i..i + 2], 16).unwrap())
            .collect()
    }

    /// Applies (or, with `restore`, undoes) the case's folder permission modes.
    pub fn modes(models: &Path, case: &Value, restore: bool) {
        use std::os::unix::fs::PermissionsExt;
        for item in case["modes"].as_array().into_iter().flatten() {
            let mode = if restore {
                0o700
            } else {
                u32::try_from(item[1].as_u64().unwrap()).unwrap()
            };
            std::fs::set_permissions(
                models.join(item[0].as_str().unwrap()),
                std::fs::Permissions::from_mode(mode),
            )
            .unwrap();
        }
    }

    pub fn build(root: &Path, case: &Value) -> (PathBuf, PathBuf, PathBuf) {
        let models = root.join("models");
        let ini = models.join("models.ini");
        let data = root.join("data");
        match case["models"].as_str().unwrap_or("dir") {
            "missing" => {}
            "file" => std::fs::write(&models, b"").unwrap(),
            kind => {
                if kind == "link" {
                    let real = root.join("real-models");
                    std::fs::create_dir(&real).unwrap();
                    std::os::unix::fs::symlink(&real, &models).unwrap();
                } else {
                    std::fs::create_dir(&models).unwrap();
                }
                for dir in case["dirs"].as_array().into_iter().flatten() {
                    std::fs::create_dir_all(models.join(dir.as_str().unwrap())).unwrap();
                }
                let files = case["files"].as_array().cloned().unwrap_or_default();
                for file in &files {
                    let path = models.join(file[0].as_str().unwrap());
                    std::fs::create_dir_all(path.parent().unwrap()).unwrap();
                    std::fs::write(&path, b"").unwrap();
                }
                for link in case["links"].as_array().into_iter().flatten() {
                    std::os::unix::fs::symlink(
                        link[1].as_str().unwrap(),
                        models.join(link[0].as_str().unwrap()),
                    )
                    .unwrap();
                }
                for link in case["abslinks"].as_array().into_iter().flatten() {
                    let target = std::fs::canonicalize(&models)
                        .unwrap()
                        .join(link[1].as_str().unwrap());
                    std::os::unix::fs::symlink(target, models.join(link[0].as_str().unwrap()))
                        .unwrap();
                }
                match &case["ini"] {
                    Value::Null => {}
                    Value::String(_) => std::fs::create_dir(&ini).unwrap(),
                    Value::Object(o) => std::fs::write(
                        &ini,
                        match o.get("text") {
                            Some(text) => text.as_str().unwrap().as_bytes().to_vec(),
                            None => hex(o["hex"].as_str().unwrap()),
                        },
                    )
                    .unwrap(),
                    other => panic!("unknown ini {other}"),
                }
                for file in &files {
                    let ns = file[1]
                        .as_i64()
                        .map(i128::from)
                        .or_else(|| file[1].as_u64().map(i128::from))
                        .unwrap();
                    let magnitude = Duration::from_nanos(u64::try_from(ns.unsigned_abs()).unwrap());
                    let t = if ns >= 0 {
                        UNIX_EPOCH + magnitude
                    } else {
                        UNIX_EPOCH - magnitude
                    };
                    let f: SystemTime = t;
                    std::fs::File::options()
                        .write(true)
                        .open(models.join(file[0].as_str().unwrap()))
                        .unwrap()
                        .set_times(std::fs::FileTimes::new().set_accessed(f).set_modified(f))
                        .unwrap();
                }
            }
        }
        if let Value::Object(s) = &case["store"] {
            std::fs::create_dir(&data).unwrap();
            let db = data.join("model_loader.db");
            if let Some(bytes) = s.get("bytes") {
                std::fs::write(&db, hex(bytes.as_str().unwrap())).unwrap();
            } else {
                let c = Connection::open(&db).unwrap();
                let journal = s["journal"].as_str().unwrap().to_uppercase();
                let _: String = c
                    .query_row(&format!("PRAGMA journal_mode={journal}"), [], |r| r.get(0))
                    .unwrap();
                for statement in s["sql"].as_array().unwrap() {
                    c.execute_batch(statement.as_str().unwrap()).unwrap();
                }
            }
        }
        (models, ini, data)
    }
}

/// A one-shot fake for the Python child: records the request line and answers fixed JSON.
async fn legacy() -> (String, tokio::task::JoinHandle<String>) {
    use tokio::io::{AsyncReadExt, AsyncWriteExt};
    let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
    let base = format!("http://{}", listener.local_addr().unwrap());
    let task = tokio::spawn(async move {
        let (mut socket, _) = listener.accept().await.unwrap();
        let mut seen = Vec::new();
        let mut buf = [0u8; 4096];
        while !seen.windows(4).any(|w| w == b"\r\n\r\n") {
            let n = socket.read(&mut buf).await.unwrap();
            assert!(n > 0);
            seen.extend_from_slice(&buf[..n]);
        }
        let body = br#"{"legacy":true}"#;
        let head = format!(
            "HTTP/1.1 200 OK\r\ncontent-type: application/json\r\ncontent-length: {}\r\nconnection: close\r\n\r\n",
            body.len()
        );
        socket.write_all(head.as_bytes()).await.unwrap();
        socket.write_all(body).await.unwrap();
        String::from_utf8_lossy(&seen)
            .lines()
            .next()
            .unwrap()
            .to_owned()
    });
    (base, task)
}

#[tokio::test]
async fn python_mode_forwards_get_unchanged() {
    let (base, seen) = legacy().await;
    let answer = send(state(None, &base), "GET", PATH, true).await;
    assert_eq!(answer.body, br#"{"legacy":true}"#);
    assert_eq!(seen.await.unwrap(), "GET /api/v1/models/updates HTTP/1.1");
}

#[tokio::test]
async fn neighbouring_routes_stay_with_python() {
    let dir = tempfile::tempdir().unwrap();
    let models = dir.path().join("models");
    let data = store(dir.path());
    for path in ["/api/v1/models", "/api/v1/models/detail?key=synthetic.gguf"] {
        let (base, seen) = legacy().await;
        let answer = send(
            state(Some((&models, &models.join("models.ini"), &data)), &base),
            "GET",
            path,
            true,
        )
        .await;
        assert_eq!(answer.body, br#"{"legacy":true}"#, "{path}");
        assert_eq!(seen.await.unwrap(), format!("GET {path} HTTP/1.1"));
    }
}

#[tokio::test]
async fn native_route_keeps_auth_and_non_get_policy() {
    let dir = tempfile::tempdir().unwrap();
    let models = dir.path().join("models");
    let data = store(dir.path());
    let roots = (models.as_path(), models.join("models.ini"), data.as_path());
    let make = || state(Some((roots.0, &roots.1, roots.2)), "http://127.0.0.1:9");
    let unauthorized = send(make(), "GET", PATH, false).await;
    assert_eq!(unauthorized.status, 401);
    assert_eq!(unauthorized.body, br#"{"error":"unauthorized"}"#);
    for method in ["POST", "PUT", "DELETE", "HEAD"] {
        let answer = send(make(), method, PATH, true).await;
        assert_eq!(answer.status, 405, "{method}");
    }
    let slash = send(make(), "GET", "/api/v1/models/updates/", true).await;
    assert_eq!(slash.status, 404);
}
